 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`).
 * @returns {Object} A structured log entry.
 ***/
function _synthesizedLogEntry(chunk, meta = {}) {
	_logEntryIdCounter += 1;
	const { kind, feed } = _logEntryKindFromText(chunk);
	// Only a plain bag spreads into meta: exotic inputs (strings, Dates,
	// arrays) degrade to {} instead of scattering characters into the entry.
	const cleanedMeta = redactDeepStrings(meta || {});
	const metaBag =
		cleanedMeta && typeof cleanedMeta === "object" && !Array.isArray(cleanedMeta)
			? cleanedMeta
			: {};
	return {
		id: `log-${_logEntryIdCounter}`,
		ts: new Date().toISOString(),
		feed,
		feeds: [feed],
		kind,
		turn: null,
		// Redacted at synthesis so command output, git lines, and runner
		// text frames can never store secrets or PII. Clean text passes
		// through byte-identical.
		text: redactSecretsText(String(chunk)),
		meta: { source: "process-log", ...metaBag },
	};
}

/***
 * MARK: _capLogEntries
 * @description Keeps at most `config.logEntriesMaxCount` entries on a task,
 *   dropping the oldest and recording the eviction under a single updating
 *   marker entry (mirrors the streamer's eviction behaviour).
 * @example _capLogEntries(task)
 * @param {Object} task
 * @returns {void}
 ***/
function _capLogEntries(task) {
	const max = config.logEntriesMaxCount;
	if (!Array.isArray(task.logEntries) || task.logEntries.length <= max) return;
	const existingMarker = task.logEntries[0];
	const hasMarker = existingMarker?.meta?.evictedCount !== undefined;
	// Reserve one slot for the marker so the cap holds after it is unshifted.
	const keepTarget = hasMarker ? max : max - 1;
	const overflow = task.logEntries.length - keepTarget;
	if (overflow <= 0) return;
	task.logEntries.splice(hasMarker ? 1 : 0, overflow);
	const markerText = `[INFO] (${overflow} earlier log entries evicted)`;
	if (hasMarker) {
		const previousCount = existingMarker.meta.evictedCount + overflow;
		existingMarker.text = `[INFO] (${previousCount} earlier log entries evicted)`;
		existingMarker.meta = { evictedCount: previousCount };
	} else {
		_logEntryIdCounter += 1;
		task.logEntries.unshift({
			id: `log-${_logEntryIdCounter}`,
			ts: new Date().toISOString(),
			feed: "main",
			feeds: ["main"],
			kind: "system",
			turn: null,
			text: markerText,
			meta: { evictedCount: overflow },
		});
	}
}

/***
 * MARK: parseLegacyProcessLogText
 * @description Parses legacy rendered process-log text (line-based tag
 *   grammar) into structured entries (blank lines dropped, consecutive
 *   duplicates de-duped) so tasks predating the structured-entries era still
 *   serve feeds. Shared by the markdown legacy-section synthesis
 *   (`parseTaskMarkdown`) and the in-memory feed fallback below — it is a
 *   read-only migration path, never a second storage format.
 * @example parseLegacyProcessLogText('[INFO] a\n[INFO] a') => [entry('[INFO] a')]
 * @param {string} text
 * @returns {Array<Object>} Structured log entries.
 ***/
export function parseLegacyProcessLogText(text) {
	const source = typeof text === "string" ? text : "";
	if (!source.trim()) return [];
	const parsed = [];
	for (const line of source.split("\n")) {
		if (!line.trim()) continue;
		if (parsed.length > 0 && parsed[parsed.length - 1].text === line) continue;
		parsed.push(_synthesizedLogEntry(line));
	}
	return parsed;
}

/***
 * MARK: renderLogEntriesText
 * @description The ONE shared renderer from structured log entries to legacy
 *   tag-grammar text — every text view is derived here at read time, never
 *   stored. With a `feed` option only that feed's entries render; without
 *   one, the combined main+tools narrative renders (thinking entries stay
 *   out, mirroring the streamer's combined view).
 * @example renderLogEntriesText(entries) => "[AGENT] reasoning…\n[TOOL] bash(…)"
 * @example renderLogEntriesText(entries, { feed: 'tools' }) => "[TOOL] bash(…)"
 * @param {Array<Object>} entries
 * @param {{ feed?: string }} [opts]
 * @returns {string}
 ***/
export function renderLogEntriesText(entries, { feed } = {}) {
	const selected = (Array.isArray(entries) ? entries : []).filter((entry) => {
		if (!entry) return false;
		const placed = Array.isArray(entry.feeds) ? entry.feeds : [entry.feed];
		if (feed) return placed.includes(feed);
		return placed.includes("main") || placed.includes("tools");
	});
	return selected.map((entry) => entry.text).join("\n");
}

/***
 * MARK: _logEntriesForFeed
 * @description Collects a task's entries placed on one feed (main/thinking/
 *   tools), bounded to `config.logEntriesMaxCount`. Structured entries are
 *   the single storage path; the legacy-text fallback only exists for tasks
 *   still carrying a pre-migration `processLogs` string (read-only).
 * @example _logEntriesForFeed(task, 'thinking') => [thinkingEntry, …]
 * @param {Object} task
 * @param {string} feed
 * @returns {Array<Object>} The feed's entries, oldest first.
 ***/
export function _logEntriesForFeed(task, feed) {
	const structured = Array.isArray(task?.logEntries)
		? task.logEntries.filter(Boolean)
		: [];
	const all =
		structured.length > 0
			? structured
			: parseLegacyProcessLogText(task?.processLogs);
	const matching = all.filter((entry) =>
		(Array.isArray(entry.feeds) ? entry.feeds : [entry.feed]).includes(feed),
	);
	const capped = { logEntries: matching };
	_capLogEntries(capped);
	return capped.logEntries;
}

/***
 * MARK: _appendLogEntries
 * @description Appends structured log entries to task.logEntries, capping the
 *   array to `config.logEntriesMaxCount`.
 * @example _appendLogEntries(task, streamer.snapshot().entries)
 * @param {Object} task
 * @param {Array<Object>} newEntries
 * @returns {void}
 ***/
export function _appendLogEntries(task, newEntries) {
	if (!task || !Array.isArray(newEntries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	for (const entry of newEntries) {
		if (entry) task.logEntries.push(entry);
	}
	_capLogEntries(task);
}

/***
 * MARK: _replaceLogEntries
 * @description Replaces the log entries accumulated for one stage run (the
 *   synthesized tail of the array) with the agent streamer's structured
 *   entries, upgrading turn-grouped text blocks into the task's log.
 * @example _replaceLogEntries(task, startIndex, result.logEntries)
 * @param {Object} task
 * @param {number} startIndex - Index where the stage's entries begin.
 * @param {Array<Object>} entries - The structured entries for the stage.
 * @returns {void}
 ***/
export function _replaceLogEntries(task, startIndex, entries) {
	if (!task || !Array.isArray(entries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	const safeStart = Math.max(0, Math.min(startIndex, task.logEntries.length));
	task.logEntries.splice(safeStart);
	_appendLogEntries(task, entries);
}

/***
 * MARK: _appendProcessLog
 * @description Appends a rendered log chunk to the task's structured
 *   `logEntries` as one synthesized entry — the single log storage path
 *   (agent streamer entries replace the synthesized ones when the stage
 *   result arrives). Growth is bounded by `config.logEntriesMaxCount` with
 *   an eviction marker; the historical rendered-text copy
 *   (`task.processLogs`) is gone and every text view is derived from entries
 *   at read time via `renderLogEntriesText`.
 * @example _appendProcessLog(task, '[GIT] Switched to main')
 * @param {Object} task
 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`).
 * @returns {void}
 ***/
export function _appendProcessLog(task, chunk, meta = {}) {
	if (!task || !chunk) return;
	_appendLogEntries(task, [_synthesizedLogEntry(String(chunk).trim(), meta)]);
}

/**
 * MARK: logEntryModel
 * @description Pure model for the task Logs tab. Turns a task's structured
 *   log entries (`task.logEntries`, produced by the agent log streamer) into
 *   grouped, filterable, renderable views — and falls back to parsing the
 *   legacy `task.processLogs` text (line-based tag grammar) so old tasks keep
 *   rendering exactly as before.
 *
 *   The tag grammar is the shared `classifyLogLineTag`
 *   (`shared/logTagGrammar.js`) — the same module the API-side synthesis
 *   reads, so stored history and this parse can never disagree:
 *     [TOOL] [RESULT]      -> kind "tool"       (tools feed)
 *     [THINKING]           -> kind "thinking"   (thinking feed)
 *     [USAGE]              -> kind "telemetry"  (telemetry feed)
 *     [RAW]                -> kind "raw"        (raw feed)
 *     [PERM] [PLAN]        -> kind "permission"/"plan" (main feed)
 *     [ERROR] [FAIL]       -> kind "error"      (main feed)
 *     [AGENT]              -> kind "assistant"  (main feed)
 *     [INFO] [SYSTEM] [GIT] [CI] [CI/CMD] [HUMAN] [WARN] -> kind "system"
 *     untagged text        -> kind "assistant"  (main feed)
 */

import { classifyLogLineTag } from '../../../../shared/logTagGrammar.js';

export const LOG_FEEDS = ['ALL', 'ASSISTANT', 'TOOLS', 'THINKING', 'SYSTEM', 'TELEMETRY', 'RAW'];

/***
 * MARK: legacyLogEntryId
 * @description Stable synthetic id for a parsed legacy log line.
 ***/
let legacyEntryCounter = 0;
const legacyLogEntryId = () => {
  legacyEntryCounter += 1;
  return `legacy-log-${legacyEntryCounter}`;
};

/***
 * MARK: entryFromLogLine
 * @description Maps one rendered log line to a structured entry using the
 *   shared tag grammar (`classifyLogLineTag`) — the single source this
 *   parse and the backend synthesis both read, so a tag can never
 *   classify one way in stored history and another way live. Untagged
 *   text is assistant narrative.
 * @example entryFromLogLine('[TOOL] bash("ls")') => { kind: 'tool', feed: 'tools', text: '…' }
 * @param {string} line
 * @returns {Object} A structured log entry.
 ***/
export function entryFromLogLine(line) {
  const { kind, feed } = classifyLogLineTag(line);
  return {
    id: legacyLogEntryId(),
    ts: null,
    feed,
    feeds: [feed],
    kind,
    turn: null,
    text: String(line),
    meta: { source: 'legacy-process-logs' },
  };
}

/***
 * MARK: parseLegacyProcessLogs
 * @description Parses the legacy `task.processLogs` text into structured
 *   entries: blank lines are dropped, consecutive duplicates are de-duped
 *   (the exact behavior of today's line-based Logs tab).
 * @example parseLegacyProcessLogs('[INFO] a\n[INFO] a') => [entry('[INFO] a')]
 * @param {string} text
 * @returns {Array<Object>} Structured log entries.
 ***/
export function parseLegacyProcessLogs(text) {
  if (!text || typeof text !== 'string') return [];
  const lines = text.split('\n').filter((l) => l.trim());
  const result = [];
  for (const line of lines) {
    if (result.length === 0 || result.at(-1).text !== line) {
      result.push(entryFromLogLine(line));
    }
  }
  return result;
}

/***
 * MARK: normalizeEntries
 * @description Returns the task's structured log entries when present, or
 *   synthesizes them from the legacy processLogs text otherwise. WebSocket
 *   process lines (live system output) are appended as system entries.
 * @example normalizeEntries(task) => [entry, …]
 * @param {Object} task - The task (may carry logEntries and/or processLogs).
 * @param {Array<Object>} [wsProcessLines] - Live process:stdout lines from the WebSocket.
 * @returns {Array<Object>} Structured log entries.
 ***/
export function normalizeEntries(task, wsProcessLines = []) {
  const structured = Array.isArray(task?.logEntries) ? task.logEntries.filter(Boolean) : [];
  const base = structured.length > 0 ? [...structured] : parseLegacyProcessLogs(task?.processLogs);
  // Frames already persisted (keyed by lane + execution + seq) must not
  // reappear as live lines after a refetch: the socket pushes each frame
  // the moment it is ingested, and the same frame lands in stored entries
  // on the next task fetch. The lane prefix matters: the text lane
  // (process:stdout) and the structured lane (PROCESS_LOG_ENTRIES) keep
  // INDEPENDENT seq counters on the same execution, so a bare
  // `executionId:seq` key could collide across lanes during the fallback
  // transition and hide a frame that was never stored. Frames without an
  // identity (legacy CI lines) always pass through, as before.
  const storedKeys = new Set();
  for (const entry of base) {
    const meta = entry?.meta;
    if (meta && meta.executionId != null && meta.seq != null) {
      const lane = meta.source === 'runner-structured' ? 'structured' : 'text';
      storedKeys.add(`${lane}:${meta.executionId}:${meta.seq}`);
    }
  }
  const live = [];
  for (const p of Array.isArray(wsProcessLines) ? wsProcessLines : []) {
    if (!p) continue;
    if (p.executionId != null && p.seq != null) {
      const lane = p.entry && typeof p.entry === 'object' ? 'structured' : 'text';
      if (storedKeys.has(`${lane}:${p.executionId}:${p.seq}`)) {
        continue;
      }
    }
    // Structured live entries (`PROCESS_LOG_ENTRIES` frames): the backend
    // record rides along untouched — same shape as stored history, so the
    // viewer renders tool cards, timings, and expandable details live.
    if (p.entry && typeof p.entry === 'object') {
      live.push({
        ...p.entry,
        meta: {
          ...(p.entry.meta || {}),
          source: p.entry.meta?.source || 'ws-log-entries',
          ...(p.executionId != null ? { executionId: p.executionId } : {}),
          ...(p.seq != null ? { seq: p.seq } : {}),
          ...(p.runnerId != null ? { runnerId: p.runnerId } : {}),
        },
      });
      continue;
    }
    // WS records carry a `[Project] ` prefix; strip one leading bracket
    // group so the tag grammar classifies the actual line kind.
    const line = p.raw || `${p.tag || '[INFO]'} ${p.text || ''}`;
    const entry = entryFromLogLine(String(line).replace(/^\[[^\]\n]+\] (?=\[)/, ''));
    entry.meta = {
      ...(entry.meta || {}),
      source: 'ws-process-logs',
      ...(p.executionId != null ? { executionId: p.executionId } : {}),
      ...(p.seq != null ? { seq: p.seq } : {}),
      ...(p.runnerId != null ? { runnerId: p.runnerId } : {}),
    };
    live.push(entry);
  }
  return [...base, ...live];
}

/***
 * MARK: groupByTurn
 * @description Groups entries into ordered turns for the grouped rendering.
 *   Entries without a turn (legacy parse) all land in one un-numbered group.
 * @example groupByTurn(entries) => [{ turn: 1, entries: [...] }, …]
 * @param {Array<Object>} entries
 * @returns {Array<{turn: number|null, entries: Array<Object>}>}
 ***/
export function groupByTurn(entries) {
  const groups = [];
  for (const entry of entries) {
    const turn = Number.isFinite(entry?.turn) ? entry.turn : null;
    const last = groups.at(-1);
    if (last && last.turn === turn) {
      last.entries.push(entry);
    } else {
      groups.push({ turn, entries: [entry] });
    }
  }
  return groups;
}

/***
 * MARK: feedMatchesEntry
 * @description Whether an entry belongs to a feed chip. ALL is the combined
 *   main terminal view (main + tools entries — full thinking blocks stay on
 *   the THINKING chip and telemetry/raw records stay on their own chips so
 *   they never leak into the narrative or copy). Errors surface under the
 *   SYSTEM chip (still color-highlighted).
 * @example feedMatchesEntry('SYSTEM', { kind: 'error' }) => true
 * @param {string} feed - One of LOG_FEEDS.
 * @param {Object} entry
 * @returns {boolean}
 ***/
export function feedMatchesEntry(feed, entry) {
  const entryFeeds = Array.isArray(entry.feeds) ? entry.feeds : [entry.feed];
  if (!feed || feed === 'ALL') {
    return entryFeeds.some((f) => f === 'main' || f === 'tools');
  }
  if (feed === 'ASSISTANT') return entry.kind === 'assistant';
  if (feed === 'TOOLS') return entry.kind === 'tool';
  // The dedicated thinking feed shows the full blocks, not the markers.
  if (feed === 'THINKING') return entry.kind === 'thinking' && !entry.meta?.collapsed;
  if (feed === 'SYSTEM')
    return (
      entry.kind === 'system' ||
      entry.kind === 'error' ||
      entry.kind === 'permission' ||
      entry.kind === 'plan'
    );
  if (feed === 'TELEMETRY') return entry.kind === 'telemetry';
  if (feed === 'RAW') return entry.kind === 'raw';
  return true;
}

/***
 * MARK: filterEntries
 * @description Filters entries by feed chip and free-text search (case
 *   insensitive, against the rendered text plus the expandable detail, tool
 *   names/args/results, and entry metadata — so a tool name, command, or
 *   error string hidden in a payload still matches).
 * @example filterEntries(entries, { feed: 'TOOLS', search: 'bash' })
 * @param {Array<Object>} entries
 * @param {{feed?: string, search?: string}} [criteria]
 * @returns {Array<Object>} The matching entries.
 ***/
export function filterEntries(entries, criteria = {}) {
  const { feed = 'ALL', search = '' } = criteria;
  const needle = String(search).trim().toLowerCase();
  return (entries || []).filter((entry) => {
    if (!feedMatchesEntry(feed, entry)) return false;
    if (needle) {
      let hay = '';
      try {
        const pieces = [
          entry?.text,
          entry?.title,
          renderEntryDetail(entry)?.detail,
          entry?.meta?.toolName,
          entry?.meta?.toolCallId,
          entry?.meta?.output,
          entry?.meta?.error,
          entry?.tool?.name,
          entry?.tool?.callId,
          entry?.tool?.args,
          entry?.tool?.result,
          entry?.tool?.partials,
          entry?.meta,
          entry?.tool,
        ];
        hay = pieces
          .map((piece) =>
            piece == null
              ? ''
              : typeof piece === 'string'
                ? piece
                : JSON.stringify(piece),
          )
          .join('\n')
          .toLowerCase();
      } catch {
        hay = String(entry?.text || '').toLowerCase();
      }
      if (!hay.includes(needle)) return false;
    }
    return true;
  });
}

/***
 * MARK: renderEntryText
 * @description The rendered text of an entry — the entry's own text, with
 *   collapsed thinking markers expandable to their full block.
 * @example renderEntryText(entry) => "[TOOL] bash(\"ls\")"
 * @param {Object} entry
 * @param {{expandThinking?: boolean, fullTextById?: Map}} [options]
 * @returns {string}
 ***/
export function renderEntryText(entry, options = {}) {
  if (!entry) return '';
  const { expandThinking = false, fullTextById = null } = options;
  if (
    expandThinking &&
    entry.meta?.collapsed &&
    entry.meta?.fullTextId &&
    fullTextById?.has(entry.meta.fullTextId)
  ) {
    return fullTextById.get(entry.meta.fullTextId).text;
  }
  return entry.text || '';
}

/***
 * MARK: severityClass
 * @description Tailwind text classes for a rendered log line, keyed by the
 *   legacy tag grammar (colors identical to today's Logs tab). Unified-lane
 *   tags ([USAGE]/[PERM]/[PLAN]/[RAW]) reuse the closest existing tones so
 *   no new palette is introduced before the visual refactor.
 * @example severityClass('[ERROR] boom') => 'text-[#ffb4ab] font-bold'
 * @param {string} line
 * @returns {string}
 ***/
export function severityClass(line) {
  if (/\[ERROR\]|\[FAIL\]/i.test(line)) return 'text-[#ffb4ab] font-bold';
  if (/\[WARN\]/i.test(line)) return 'text-[#ffb77f] font-bold';
  if (/\[TOOL\]/i.test(line)) return 'text-[#a6e3a1] font-semibold';
  if (/\[RESULT\]/i.test(line)) return 'text-[#94e2d5]';
  if (/\[HUMAN\]/i.test(line)) return 'text-[#9acbff] font-medium';
  if (/\[INFO\]|\[SYSTEM\]|\[USAGE\]/i.test(line)) return 'text-[#c2c8ca]';
  if (/\[PERM\]|\[PLAN\]/i.test(line)) return 'text-[#ffb77f] font-medium';
  if (/\[RAW\]/i.test(line)) return 'text-[#c2c8ca]';
  if (/\[AGENT\]/i.test(line)) return 'text-[#7bdb85] font-medium';
  if (/\[CI\]|\[CI\/CMD\]/i.test(line)) return 'text-[#ffb77f]';
  return 'text-on-surface';
}

/***
 * MARK: renderEntryDetail
 * @description Typed detail view for one entry: `{ summary, detail }`.
 *   `summary` is the inline line (the entry's own text); `detail` is the
 *   full payload for expand affordances — full tool output, usage JSON,
 *   permission/plan fields, or the bounded raw wire source. Entries without
 *   a typed payload return `{ summary: text, detail: null }` so panels can
 *   skip the expand affordance.
 * @example renderEntryDetail({ kind: 'telemetry', usage: {...} }) => { summary: '[USAGE] …', detail: '{…}' }
 * @param {Object} entry
 * @returns {{summary: string, detail: string|null}}
 ***/
export function renderEntryDetail(entry) {
  if (!entry) return { summary: '', detail: null };
  const summary = entry.text || '';
  const kind = entry.kind;
  if (kind === 'tool') {
    const output =
      entry.tool?.result ||
      entry.tool?.partials ||
      entry.meta?.output ||
      null;
    return {
      summary,
      detail: typeof output === 'string' && output && output !== summary ? output : null,
    };
  }
  if (kind === 'telemetry') {
    if (entry.usage && typeof entry.usage === 'object') {
      let detail = null;
      try {
        detail = JSON.stringify(entry.usage, null, 2);
      } catch {
        detail = null;
      }
      return { summary, detail };
    }
    return { summary, detail: null };
  }
  if (kind === 'permission' || kind === 'plan') {
    return { summary, detail: null };
  }
  if (kind === 'raw') {
    const source = entry.evidence?.sourceEvent;
    return {
      summary,
      detail: typeof source === 'string' && source ? source : null,
    };
  }
  if (kind === 'thinking' && entry.meta?.collapsed) {
    return { summary, detail: null };
  }
  return { summary, detail: null };
}

/***
 * MARK: fullTextIndex
 * @description Indexes entries by id so collapsed thinking markers can look
 *   up their full thinking block.
 * @example fullTextIndex(entries).get(marker.meta.fullTextId)?.text
 * @param {Array<Object>} entries
 * @returns {Map} Map of entry id -> entry.
 ***/
export function fullTextIndex(entries) {
  return new Map((entries || []).map((entry) => [entry.id, entry]));
}

/***
 * MARK: isResultEntry
 * @description Whether an entry is a tool result line (rendered indented
 *   under its tool call).
 * @example isResultEntry({ text: '[RESULT] ok' }) => true
 * @param {Object} entry
 * @returns {boolean}
 ***/
export function isResultEntry(entry) {
  return String(entry?.text || '').startsWith('[RESULT]');
}

// node env pin: pure-logic suite (no DOM needs); skips the DOM env cost per CI-wall budget.
// @vitest-environment node
// Run in the lighter node environment: this suite is pure logic with
// no DOM needs (skips jsdom setup, keeps the CI suite fast).
// @vitest-environment node
import { describe, it, expect } from 'vitest';
import {
  LOG_FEEDS,
  entryFromLogLine,
  parseLegacyProcessLogs,
  normalizeEntries,
  groupByTurn,
  feedMatchesEntry,
  filterEntries,
  renderEntryDetail,
  renderEntryText,
  severityClass,
  fullTextIndex,
  isResultEntry,
} from './logEntryModel';

describe('logEntryModel — legacy parsing', () => {
  it('maps the tag grammar to entry kinds and feeds', () => {
    expect(entryFromLogLine('[TOOL] bash("ls")')).toMatchObject({ kind: 'tool', feed: 'tools' });
    expect(entryFromLogLine('[RESULT] ok')).toMatchObject({ kind: 'tool', feed: 'tools' });
    expect(entryFromLogLine('[THINKING] (12 chars)')).toMatchObject({
      kind: 'thinking',
      feed: 'thinking',
    });
    expect(entryFromLogLine('[ERROR] boom')).toMatchObject({ kind: 'error', feed: 'main' });
    expect(entryFromLogLine('[AGENT] reasoning')).toMatchObject({
      kind: 'assistant',
      feed: 'main',
    });
    expect(entryFromLogLine('[INFO] boot')).toMatchObject({ kind: 'system', feed: 'main' });
    expect(entryFromLogLine('[GIT] main')).toMatchObject({ kind: 'system', feed: 'main' });
    expect(entryFromLogLine('[USAGE] tokens=1/2/3')).toMatchObject({
      kind: 'telemetry',
      feed: 'telemetry',
    });
    expect(entryFromLogLine('[RAW] x: unmapped')).toMatchObject({ kind: 'raw', feed: 'raw' });
    expect(entryFromLogLine('[PERM] request bash')).toMatchObject({
      kind: 'permission',
      feed: 'main',
    });
    expect(entryFromLogLine('[PLAN] updated')).toMatchObject({ kind: 'plan', feed: 'main' });
    // Shared-grammar alignment: lowercase error tags and lowercase
    // [stdout] wrappers classify like their caps forms (as they do in the
    // backend synthesis and the category layer).
